begin;
select plan(20);
update public.pos_tip_capture_control set execution_enabled=false;
insert into auth.users(id,email,raw_user_meta_data) values('7e000000-0000-4000-8000-000000000001','stripe-reconciliation@example.invalid','{}');
update public.profiles set role_id=(select id from public.roles where code='owner'),active=true where id='7e000000-0000-4000-8000-000000000001';
update public.store_settings set test_ordering_enabled=true,pickup_minimum_cents=0,tax_rate_basis_points=0;
insert into public.menu_categories(id,name) values('7e000000-0000-4000-8000-000000000002','Webhook regression');
insert into public.menu_items(id,category_id,name,base_price_cents,pos_visible) values('7e000000-0000-4000-8000-000000000003','7e000000-0000-4000-8000-000000000002','Synthetic webhook fixture',2000,true);
set local role authenticated;
select set_config('request.jwt.claim.sub','7e000000-0000-4000-8000-000000000001',true);
select set_config('recon.order',(public.wayne_create_pos_order(jsonb_build_object('idempotency_key',gen_random_uuid(),'source','pos','customer_mode','walk_in','fulfillment_type','pickup','payment_method','test_manual','items',jsonb_build_array(jsonb_build_object('menu_item_id','7e000000-0000-4000-8000-000000000003','quantity',1,'modifiers','[]'::jsonb))))->>'id'),true);
reset role;
select set_config('request.jwt.claim.sub','',true);
insert into public.payments(id,order_id,provider,provider_payment_id,method,amount_cents,status,metadata)
values('7e000000-0000-4000-8000-000000000004',current_setting('recon.order')::uuid,'stripe','pi_pgtap_normal','card',2000,'authorized','{}');
set local role service_role;
select public.wayne_settle_stripe_payment('40000000-0000-4000-8000-000000000001','{"provider_payment_id":"pi_pgtap_normal","status":"failed","amount_cents":2000}');
select is((select status from public.payments where id='7e000000-0000-4000-8000-000000000004'),'authorized','earlier failed read cannot undo authorization');
select public.wayne_settle_stripe_payment('40000000-0000-4000-8000-000000000001','{"provider_payment_id":"pi_pgtap_normal","status":"captured","amount_cents":2000}');
select is((select status from public.payments where id='7e000000-0000-4000-8000-000000000004'),'captured','authoritative success settles ordinary payment');
select is((select amount_cents from public.payments where id='7e000000-0000-4000-8000-000000000004'),2000,'captured amount matches provider');
select public.wayne_settle_stripe_payment('40000000-0000-4000-8000-000000000001','{"provider_payment_id":"pi_pgtap_normal","status":"voided","amount_cents":2000}');
select is((select status from public.payments where id='7e000000-0000-4000-8000-000000000004'),'captured','delayed cancellation cannot undo captured money');
select public.wayne_settle_stripe_payment('40000000-0000-4000-8000-000000000001','{"provider_payment_id":"pi_pgtap_normal","status":"authorized","amount_cents":2000}');
select is((select status from public.payments where id='7e000000-0000-4000-8000-000000000004'),'captured','delayed authorization cannot undo captured money');
reset role;
update public.payments set status='failed',failed_at=now() where id='7e000000-0000-4000-8000-000000000004';
set local role service_role;
select public.wayne_settle_stripe_payment('40000000-0000-4000-8000-000000000001','{"provider_payment_id":"pi_pgtap_normal","status":"captured","amount_cents":2000}');
select is((select status from public.payments where id='7e000000-0000-4000-8000-000000000004'),'captured','previously failed normal ledger can recover');
select ok((select failed_at is not null from public.payments where id='7e000000-0000-4000-8000-000000000004'),'historical failure timestamp remains');
select is((select count(*) from public.order_events where order_id=current_setting('recon.order')::uuid and event_type='payment.reconciled'),1::bigint,'recovery leaves one historical correction event');
reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub','7e000000-0000-4000-8000-000000000001',true);
select set_config('recon.order',(public.wayne_create_pos_order(jsonb_build_object('idempotency_key',gen_random_uuid(),'source','pos','customer_mode','walk_in','fulfillment_type','pickup','payment_method','test_manual','items',jsonb_build_array(jsonb_build_object('menu_item_id','7e000000-0000-4000-8000-000000000003','quantity',1,'modifiers','[]'::jsonb))))->>'id'),true);
reset role;
select set_config('request.jwt.claim.sub','',true);
insert into public.payments(id,order_id,provider,provider_payment_id,method,amount_cents,status,metadata)
values('7e000000-0000-4000-8000-000000000005',current_setting('recon.order')::uuid,'stripe','pi_pgtap_original','card',2000,'failed','{"tip_adjust":true}');
insert into public.pos_tip_operations(id,payment_id,order_id,workspace_id,location_id,original_provider_id,authorized_cents,requested_tip_cents,origin,plan,replacement_id)
select '7e000000-0000-4000-8000-000000000006',p.id,p.order_id,p.workspace_id,p.location_id,p.provider_payment_id,2000,500,'pgtap','{"mode":"replacement","amount_cents":2500,"fallback_amount_cents":2000}','pi_pgtap_replacement' from public.payments p where p.id='7e000000-0000-4000-8000-000000000005';
set local role service_role;
select public.wayne_settle_stripe_payment('7e000000-0000-4000-8000-000000000099','{"provider_payment_id":"pi_pgtap_replacement","status":"captured","amount_cents":2500}');
select is((select status from public.payments where id='7e000000-0000-4000-8000-000000000005'),'failed','wrong workspace cannot settle a saved replacement');
select public.wayne_settle_stripe_payment('40000000-0000-4000-8000-000000000001','{"provider_payment_id":"pi_pgtap_replacement","status":"captured","amount_cents":2500}');
select is((select state from public.pos_tip_operations where id='7e000000-0000-4000-8000-000000000006'),'succeeded','saved replacement commits a durable receipt');
select is((select status from public.payments where id='7e000000-0000-4000-8000-000000000005'),'captured','failed replacement ledger repaired');
select is((select amount_cents from public.payments where id='7e000000-0000-4000-8000-000000000005'),2500,'ledger records full replacement amount');
select is((select tip_cents from public.orders where id=current_setting('recon.order')::uuid),500,'tip applied once');
select is((select total_cents from public.orders where id=current_setting('recon.order')::uuid),2500,'order total includes tip');
select is((select provider_payment_id from public.payments where id='7e000000-0000-4000-8000-000000000005'),'pi_pgtap_replacement','ledger points at saved replacement');
select ok((select release_pending from public.pos_tip_operations where id='7e000000-0000-4000-8000-000000000006'),'original hold remains pending release after receipt');
select public.wayne_settle_stripe_payment('40000000-0000-4000-8000-000000000001','{"provider_payment_id":"pi_pgtap_replacement","status":"captured","amount_cents":2500}');
select is((select count(*) from public.order_events where order_id=current_setting('recon.order')::uuid and event_type='payment.tip_captured'),1::bigint,'duplicate receipt does not add another tip');
select ok(not has_function_privilege('authenticated','public.wayne_settle_stripe_payment(uuid,jsonb)','execute'),'webhook settlement is service-only');
select throws_ok($$select public.wayne_settle_stripe_payment('40000000-0000-4000-8000-000000000001','{"provider_payment_id":"pi_pgtap_replacement","status":"captured","amount_cents":2501}')$$,'22023','Conflicting provider result','conflicting amount cannot change receipt');
select ok(not (select execution_enabled from public.pos_tip_capture_control),'recovery leaves capture execution paused');
select * from finish();
rollback;
